{"content": "import pandas as pd

def find_top_authors(filename, output):
    # Load the dataset
    df = pd.read_csv(filename)

    # Dictionary to store author data
    author_data = {}

    for _, row in df.iterrows():
        # Process primary item
        p_author = row['primary_item_author']
        p_price = row['primary_item_unit_price']
        p_qty = row['primary_item_quantity']

        if pd.notna(p_author):
            if p_author not in author_data:
                author_data[p_author] = {'UnitsSold': 0, 'GrossSales': 0.0}
            author_data[p_author]['UnitsSold'] += int(p_qty)
            author_data[p_author]['GrossSales'] += float(p_price) * int(p_qty)

        # Process secondary item
        s_author = row['secondary_item_author']
        s_price = row['secondary_item_unit_price']
        s_qty = row['secondary_item_quantity']

        if pd.notna(s_author):
            if s_author not in author_data:
                author_data[s_author] = {'UnitsSold': 0, 'GrossSales': 0.0}
            author_data[s_author]['UnitsSold'] += int(s_qty)
            author_data[s_author]['GrossSales'] += float(s_price) * int(s_qty)

    # Convert dictionary to DataFrame
    result_df = pd.DataFrame.from_dict(author_data, orient='index').reset_index()
    result_df.rename(columns={'index': 'Author'}, inplace=True)

    # Sort by GrossSales descending
    top_authors = result_df.sort_values(by='GrossSales', ascending=False).head(10)

    # Save to CSV
    top_authors.to_csv(output, index=False)
    print(f"Top authors saved to {output}")

if __name__ == "__main__":
    find_top_authors('bookstore_orders.csv', 'top-authors.csv')
