from PIL import Image
import shutil

def analyze_green_channel(path):
    with Image.open(path) as img:
        img = img.convert('RGB')
        width, height = img.size
        pixels = list(img.getdata())
        mid_y = height // 2
        top_green = []
        bottom_green = []
        for y in range(height):
            for x in range(width):
                pixel = pixels[y * width + x]
                if y < mid_y:
                    top_green.append(pixel[1])
                else:
                    bottom_green.append(pixel[1])
        mean_top = sum(top_green) / len(top_green)
        mean_bottom = sum(bottom_green) / len(bottom_green)
        return mean_top, mean_bottom

def sort_normal_maps(source_dir, ogl_dir, d3d_dir):
    if not os.path.exists(ogl_dir):
        os.makedirs(ogl_dir)
    if not os.path.exists(d3d_dir):
        os.makedirs(d3d_dir)

    for filename in os.listdir(source_dir):
        if filename.endswith('.png'):
            file_path = os.path.join(source_dir, filename)
            try:
                mean_top, mean_bottom = analyze_green_channel(file_path)
                # In OpenGL, Y is up (higher green at top)
                # In D3D, Y is down (higher green at bottom)
                if mean_top > mean_bottom:
                    print(f"{filename} is OpenGL (Top: {mean_top:.2f}, Bottom: {mean_bottom:.2f})")
                    shutil.copy(file_path, os.path.join(ogl_dir, filename))
                else:
                    print(f"{filename} is D3D (Top: {mean_top:.2f}, Bottom: {mean_bottom:.2f})")
                    shutil.copy(file_path, os.path.join(d3d_dir, filename))
            except Exception as e:
                print(f"Error processing {filename}: {e}")

if __name__ == "__main__":
    sort_normal_maps('mixed', 'ogl', 'd3d')
